#!/usr/bin/env python3.13
"""No network, native wallet or fixture operations; exercise journal ownership."""
import importlib.util
import sys
import tempfile
from pathlib import Path
import unittest

# Keep the source-only tooling inventory free of import-generated bytecode.
sys.dont_write_bytecode = True

spec = importlib.util.spec_from_file_location('qa_control', Path(__file__).with_name('rgb-l1-qa-control.py'))
qa = importlib.util.module_from_spec(spec)
spec.loader.exec_module(qa)


class JournalTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix='aster-l1-control-')
        self.root = Path(self.temp.name) / 'run001'
        self.journal = qa.Journal(self.root, 'run001')
        self.event = {'run_id': 'run001', 'role': 'primary', 'event': 'fund_requested', 'id': 'run001-primary-1', 'amount_sats': 100000, 'address': 'public-test-address'}

    def tearDown(self):
        self.temp.cleanup()

    def test_identical_publication_is_one_intent(self):
        self.assertEqual(self.journal.event(self.event), ('run001-primary-1', False))
        self.assertEqual(self.journal.event(dict(self.event)), ('run001-primary-1', True))
        self.assertEqual(len(list((self.root / 'events').iterdir())), 1)

    def test_conflict_never_overwrites_original_intent(self):
        self.journal.event(self.event)
        original = (self.root / 'events/run001-primary-1.json').read_bytes()
        with self.assertRaises(ValueError): self.journal.event({**self.event, 'amount_sats': 200000})
        self.assertEqual((self.root / 'events/run001-primary-1.json').read_bytes(), original)

    def test_cross_run_missing_id_and_traversal_are_rejected(self):
        for change in [{'role': 4}, {'event': None}, {'run_id': 'other'}, {'id': 'other-primary-1'}, {'id': '../../outside'}, {'id': None}]:
            with self.assertRaises(ValueError): self.journal.event({**self.event, **change})
        self.assertEqual(list((self.root / 'events').iterdir()), [])
        with self.assertRaises(ValueError): self.journal.command('../scope')

    def test_response_requires_request_and_cannot_be_replaced(self):
        with self.assertRaises(ValueError): self.journal.reply('run001-primary-1', {'ok': True})
        self.journal.event(self.event)
        self.assertIsNone(self.journal.command('run001-primary-1'))
        self.journal.reply('run001-primary-1', {'ok': True, 'btc_send_address': 'public-return-address'})
        first = self.journal.command('run001-primary-1')
        with self.assertRaises(FileExistsError): self.journal.reply('run001-primary-1', {'ok': True})
        self.assertEqual(self.journal.command('run001-primary-1'), first)

    def test_private_duplicate_nonfinite_and_oversized_input_rejected(self):
        for value in [b'{"nested":{"mnemonic":"never log this"}}', b'{"ok":true,"ok":false}', b'{"value":NaN}', b' ' * (qa.MAX_BYTES + 1)]:
            with self.assertRaises(ValueError): qa.decode_public(value)

    def test_direct_journal_boundary_also_rejects_private_fields(self):
        with self.assertRaises(ValueError): self.journal.event({**self.event, 'mnemonic': 'never serialize'})
        self.assertEqual(list((self.root / 'events').iterdir()), [])
        self.journal.event(self.event)
        with self.assertRaises(ValueError): self.journal.reply('run001-primary-1', {'ok': True, 'secret': 'never serialize'})
        self.assertEqual(list((self.root / 'commands').iterdir()), [])

    def test_scope_identity_and_symlink_directory_cannot_change(self):
        with self.assertRaises(ValueError): qa.Journal(self.root, 'other')
        commands = self.root / 'commands'
        commands.rmdir()
        commands.symlink_to(self.root / 'events', target_is_directory=True)
        with self.assertRaises(ValueError): qa.Journal(self.root, 'run001')


if __name__ == '__main__': unittest.main()
